WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_proportion'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '比重概述', 'kp-xc-data-proportion-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"比重概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"比重约 6 题，是资料分析第二大考点。核心公式：比重 = 部分/整体。难点在于基期比重和两期比重差的计算。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"columns","content":[{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"子类"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期比重：当前时期的部分占比"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期比重：过去时期的占比"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两期比重：两个时期占比的差值"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"比重变化：占比是升还是降"}]}]}]}]},{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"比重 = A/B"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期 = A/B × (1+b)/(1+a)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"差值 = A/B × (a-b)/(1+a)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"a > b 升，a < b 降"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期比重 = 部分值(A) / 整体值(B)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期比重 = (A/B) × (1+b)/(1+a)，其中 a=部分增长率，b=整体增长率"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两期比重差 = (A/B) × (a-b)/(1+a)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"比重升降判断：a > b 则比重上升，a < b 则下降"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、秒杀技巧"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两期比重差选项差距大时：直接用「现期比重 × (a-b)」，结果偏大，选比它小的"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期比重选项差距大时：直接用「A/B × (1+b-a)」近似估算"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"比重升降判断：只需比较 a 和 b 的大小，不需要计算"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期比重公式中不要混淆分子分母的增长率"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两期比重差一定小于 |a-b|（绝对值）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"比重升降只看 a 和 b，不需要算具体值"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"比重是资料分析中区分度最高的题型。建议重点练习基期比重和两期比重差。"}]}]}]}]}$$ AS jsonb), NULL, '比重概述：现期比重、基期比重、两期比重差、比重变化。', category_node.id, CAST('["资料分析", "比重"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_proportion", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
